window.IELTS_DATA={"listening":{"easy":[{"title":"Part 1 · Swimming centre registration","subtitle":"A new student asks about an evening swimming course. Listen for names, dates and practical details.","people":{"N":"Narrator","F":"Receptionist","M":"Caller"},"lines":[["N","Part one. You will hear a telephone conversation between a caller and a receptionist at a swimming centre. You have some time to look at questions one to ten."],["F","Good afternoon, Brookfield Swimming Centre. How can I help you?"],["M","Hello. I want to join a beginner swimming course next term. I can swim a little, but I am not confident in deep water."],["F","Our Water Confidence course would be suitable. Shall I take your name first?"],["M","Yes. It is Daniel Bennett. Bennett is spelled B, E, N, N, E, T, T."],["F","Thank you, Mr Bennett. The course runs on Thursdays, not Tuesdays, and the first lesson is on the eighth of April next year."],["M","Thursday is fine. What time does it begin? I finish work at six."],["F","The building opens for evening swimmers at six, but your actual class starts at six fifteen in the evening."],["M","That gives me enough time. How long does the course last?"],["F","It is six weeks long. The total course fee is forty-eight pounds. You pay the whole amount when you register."],["M","Great. Will I need to buy any equipment?"],["F","Bring a towel and your swimming clothes. We provide the floating boards and other equipment."],["M","And who is the instructor?"],["F","Ms Lane teaches the Water Confidence class. She has worked with adult beginners for several years."],["M","Where should I go when I arrive? The main entrance was crowded last time."],["F","Use the West entrance, next to the bicycle parking. There will be a sign for evening courses."],["M","Perfect. I will register online tonight. Thanks for your help."],["F","You are very welcome. We look forward to seeing you in April."],["N","That is the end of part one."]],"instructions":"Questions 1–10. Complete the registration form. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.","questions":[{"n":1,"prompt":"Student surname: ________","answer":"Bennett","why":"The caller spells BENNETT clearly."},{"n":2,"prompt":"Course name: ________","answer":"Water Confidence","why":"The receptionist recommends the Water Confidence course."},{"n":3,"prompt":"Class day: ________","answer":"Thursday","why":"The receptionist contrasts Thursday with Tuesday."},{"n":4,"prompt":"Start time: ________ p.m.","answer":"6:15","why":"The building opens at six; the lesson begins at six fifteen.","accept":["6.15","6 15","six fifteen"]},{"n":5,"prompt":"Number of weeks: ________","answer":"6","why":"The class runs for six weeks.","accept":["six"]},{"n":6,"prompt":"Total course fee: £________","answer":"48","why":"The fee is £48 for the entire course.","accept":["forty-eight","forty eight"]},{"n":7,"prompt":"Instructor: Ms ________","answer":"Lane","why":"Ms Lane is the named instructor."},{"n":8,"prompt":"Item to bring: ________","answer":"towel","why":"The centre provides boards; students bring a towel."},{"n":9,"prompt":"Entrance to use: ________","answer":"West","why":"The West entrance is beside the bicycle parking."},{"n":10,"prompt":"First lesson: ________ April","answer":"8","why":"The receptionist says the eighth of April.","accept":["eighth"]}]},{"title":"Part 2 · Welcome to the city library","subtitle":"A librarian explains facilities and a Saturday programme.","people":{"N":"Narrator","F":"Librarian"},"lines":[["N","Part two. You will hear a librarian giving an introduction to new visitors. First, look at questions eleven to twenty."],["F","Hello, everyone, and welcome to Riverside City Library. My name is Helen and I will explain how to use our building before we begin the tour."],["F","On weekdays we open at eight thirty, but on Saturdays our doors open at nine in the morning. We close at five on Saturdays."],["F","If you have borrowed a book, return it at the blue desk just beside the main entrance. Please do not leave returned books in the café."],["F","Anyone may read in the main hall, but only people who have a library card can reserve a quiet study room. The card is free to obtain at reception."],["F","Our café is on the top floor. It used to be on the ground floor, so some old signs still point there. Please follow the new green signs."],["F","Printing is available near the computers. A black-and-white sheet costs ten pence. Colour printing costs more, but the ordinary sheets are ten pence each."],["F","Now I would like to tell you about the activities this weekend. The homework club takes place in the Cedar Room near the lift."],["F","Our story hour for young children is on Saturday mornings. It begins at ten and parents can stay with their children."],["F","At two o’clock we are running a free introduction to photography. You may use your own phone or borrow one of our cameras."],["F","You can also borrow a laptop inside the library. Each loan lasts a maximum of two hours. Please return the laptop to staff, not to a shelf."],["F","Finally, if you need any help, visit the information desk next to the lift. You will see a large blue information sign."],["F","That concludes the introduction. We can now start the tour. Please follow me."],["N","That is the end of part two."]],"instructions":"Questions 11–15: Choose A, B or C. Questions 16–20: Complete the notes with NO MORE THAN TWO WORDS AND/OR A NUMBER.","questions":[{"n":11,"prompt":"What time does the library open on Saturdays?","answer":"B","why":"8:30 is the weekday opening time, not Saturday.","choices":["A. 8:30 a.m.","B. 9:00 a.m.","C. 10:00 a.m."]},{"n":12,"prompt":"Where should visitors return borrowed books?","answer":"A","why":"The blue return desk is beside the main entrance.","choices":["A. Beside the main entrance","B. At the café","C. On the top floor"]},{"n":13,"prompt":"Who may reserve a quiet study room?","answer":"B","why":"A card is required to reserve a study room.","choices":["A. Any visitor","B. Library cardholders","C. Library employees only"]},{"n":14,"prompt":"Where is the café now?","answer":"C","why":"The café moved from the ground floor to the top floor.","choices":["A. On the ground floor","B. In the basement","C. On the top floor"]},{"n":15,"prompt":"What is the price of one black-and-white printed page?","answer":"A","why":"The standard black-and-white rate is ten pence.","choices":["A. 10 pence","B. 20 pence","C. Free"]},{"n":16,"prompt":"Homework club room: ________","answer":"Cedar","why":"The homework club is held in the Cedar Room."},{"n":17,"prompt":"Children’s story hour day: ________","answer":"Saturday","why":"Story hour is on Saturday mornings."},{"n":18,"prompt":"Free afternoon workshop topic: ________","answer":"photography","why":"The free introduction is to photography."},{"n":19,"prompt":"Maximum laptop loan: ________ hours","answer":"2","why":"Laptop loans are limited to two hours.","accept":["two"]},{"n":20,"prompt":"Information desk is next to the ________.","answer":"lift","why":"The help desk is beside the lift.","accept":["elevator"]}]},{"title":"Part 3 · A student garden project","subtitle":"Two students discuss how to create a small garden on campus.","people":{"N":"Narrator","F":"Maya","M":"Leo"},"lines":[["N","Part three. You will hear two university students talking about a campus garden project. Look at questions twenty-one to thirty."],["F","Leo, I have spoken to some students about our new garden. Most of them want plants they can use when cooking."],["M","Then let us start with herbs, rather than fruit trees or decorative flowers. Mint and basil should be easy to care for."],["F","Agreed. We still need to choose a location. The open field is large, but the wind is strong there."],["M","The courtyard behind the science building is better. It is sheltered from the wind, and there is a water tap nearby."],["F","Good. I can draw the plan, but someone needs to ask the university for permission."],["M","I can do that. I will email the facilities manager today and ask for written approval."],["F","We have two small shovels and several watering cans. Have we got gloves?"],["M","No, I checked the cupboard this morning. We still need gloves. I can buy a few pairs."],["F","How should we find volunteers? We could print posters or send emails."],["M","Why not put a short message on the student social-media page? Almost everyone reads it, and we can include a sign-up link."],["F","That sounds good. Now, the garden bed should be four metres long. The maintenance team said they can give us soil."],["M","Excellent. Shall we meet on Friday at two?"],["F","I have class until half past two, so let us meet at three in the afternoon instead."],["M","All right. Once the garden is open, we should check the plants every Monday. That way we can water them before the week gets busy."],["F","And our project report should include photographs so readers can see how the garden changes."],["M","I will bring my camera. We have enough to get started."],["N","That is the end of part three."]],"instructions":"Questions 21–25: Choose A, B or C. Questions 26–30: Complete the project notes with ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":21,"prompt":"What will the students grow first?","answer":"A","why":"They choose herbs such as mint and basil.","choices":["A. Herbs","B. Fruit trees","C. Decorative flowers"]},{"n":22,"prompt":"Why do they prefer the courtyard?","answer":"B","why":"They say the courtyard is sheltered from strong wind.","choices":["A. It is the largest space","B. It is protected from the wind","C. It is beside a bus stop"]},{"n":23,"prompt":"Who will request university permission?","answer":"C","why":"Leo offers to email the facilities manager.","choices":["A. The tutor","B. Maya","C. Leo"]},{"n":24,"prompt":"Which item do they still need to buy?","answer":"B","why":"They already have shovels and watering cans, but no gloves.","choices":["A. Watering cans","B. Gloves","C. Shovels"]},{"n":25,"prompt":"How will they invite volunteers?","answer":"C","why":"They choose the student social-media page.","choices":["A. Posters","B. Email invitations","C. Social media"]},{"n":26,"prompt":"Length of garden bed: ________ metres","answer":"4","why":"The planned bed is four metres long.","accept":["four"]},{"n":27,"prompt":"The ________ team will provide soil.","answer":"maintenance","why":"The maintenance team has offered soil."},{"n":28,"prompt":"Friday meeting time: ________ p.m.","answer":"3","why":"They reject two and settle on three.","accept":["three","3:00","3.00"]},{"n":29,"prompt":"Day for weekly garden checks: ________","answer":"Monday","why":"They will check the plants every Monday."},{"n":30,"prompt":"Project report should include ________.","answer":"photographs","why":"Photographs will show how the garden changes.","accept":["photos","pictures"]}]},{"title":"Part 4 · How bees help plants","subtitle":"A simple university lecture about pollination and gardens.","people":{"N":"Narrator","M":"Lecturer"},"lines":[["N","Part four. You will hear a lecturer talking about bees and pollination. Look at questions thirty-one to forty."],["M","Today we will look at why bees are important to plants, farms and gardens. A bee visits a flower to collect food. One important food is nectar, a sweet liquid produced by many flowers."],["M","As the bee moves around a flower, tiny grains of pollen may stick to its body. Some bees also collect pollen in special areas on their legs. When a bee visits another flower, some pollen may be transferred."],["M","This movement of pollen can help flowering plants produce seeds and fruit. Bees are not the only pollinators. Many crops depend partly on insects, including butterflies and flies."],["M","Flowers attract pollinators in different ways. Some have bright colours, while others have a strong smell. Different species of bees notice different signals."],["M","Honeybees are especially interesting because they can share information about food. A returning worker may perform dances that provide other bees with clues about the direction and distance of flowers."],["M","Many honeybees live together in large colonies. However, not every bee species is social. A great many wild bees live alone."],["M","There are several practical ways to help bees. First, harmful pesticide use should be reduced where possible and products should always be used according to their instructions."],["M","Second, choose different flowering plants. A mixture can provide food in several seasons, rather than only during a few weeks in spring."],["M","Third, remember nesting places. Some wild bees make nests in the soil. Leaving a small patch of undisturbed ground can help them."],["M","Finally, bees need water. In a garden you can place clean water in shallow dishes with stones that give insects a place to land."],["M","By providing flowers, nesting spaces and water, even a small garden can become useful to pollinating insects."],["N","That is the end of part four and the end of the listening test."]],"instructions":"Questions 31–40. Complete the lecture notes. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"prompt":"Bees collect sweet liquid called ________.","answer":"nectar","why":"Nectar is a food collected from flowers."},{"n":32,"prompt":"Some bees carry pollen on their ________.","answer":"legs","why":"Pollen can be carried on specialised areas of their legs."},{"n":33,"prompt":"Many crops rely partly on ________ for pollination.","answer":"insects","why":"The speaker mentions bees, butterflies and flies as insect pollinators."},{"n":34,"prompt":"Flowers may attract bees with bright ________.","answer":"colours","why":"Bright colours and strong smells are attracting signals.","accept":["colors"]},{"n":35,"prompt":"Honeybees share information through ________.","answer":"dances","why":"Their dances give information about flowers."},{"n":36,"prompt":"Honeybees live in large ________.","answer":"colonies","why":"The lecturer calls their social groups colonies."},{"n":37,"prompt":"Harmful pesticide use should be ________.","answer":"reduced","why":"The lecturer recommends reducing harmful pesticide use."},{"n":38,"prompt":"Plant diversity supports bees in different ________.","answer":"seasons","why":"A mixture of plants flowers at different times of year."},{"n":39,"prompt":"Some wild bees build nests in the ________.","answer":"soil","why":"The lecturer says some wild bees nest in soil."},{"n":40,"prompt":"Provide water in shallow ________.","answer":"dishes","why":"Shallow dishes with stones provide accessible water."}]}],"moderate":[{"title":"Part 1 · An art-workshop booking","subtitle":"A customer books a place on a museum workshop and corrects several details.","people":{"N":"Narrator","F":"Museum receptionist","M":"Customer"},"lines":[["N","Part one. You will hear a conversation about an evening workshop at a local museum. Look at questions one to ten."],["F","Good afternoon, Westborough Museum. You are speaking to Olivia. How may I help?"],["M","I saw an advert for your evening art workshops. I am particularly interested in printmaking, rather than painting."],["F","Certainly. We have a printmaking workshop next month. Could I take your surname?"],["M","Patel. That is P, A, T, E, L. My first name is Arjun."],["F","Thank you. The brochure lists the seventeenth of May, but we moved that session because the studio is being repaired. The new date is the nineteenth of May."],["M","That actually suits me better. Does it still begin at six thirty?"],["F","Not quite. The doors open at six fifteen, and you can collect an apron then. The short introduction starts at six forty. Please be seated before that."],["M","I remember seeing something about the Birch Studio. Is that where we meet?"],["F","That was the original plan. It has been moved to the Alder Studio on the first floor."],["M","And how much does it cost? I am studying at the university."],["F","The standard ticket is forty pounds. Booking online reduces that to thirty-five, but if you show a current student card the price is thirty-two pounds."],["M","Good. Do I pay all of that now?"],["F","Only a ten-pound deposit today. You pay the remaining amount at the museum."],["M","Is there anything I need to bring? I have my own tools."],["F","Please leave the tools at home; we provide them. However, we suggest wearing closed shoes, because the floor can become slippery."],["M","Understood. I am taking the bus. Which stop is closest?"],["F","Get off at Market Square. The stop called Museum Road sounds closer, but the pavement there is closed this month."],["M","If my timetable changes, how late can I cancel?"],["F","We need seventy-two hours notice to refund your deposit. The old policy was forty-eight hours, but it changed in September."],["M","Thank you. Please reserve one student place for me."],["F","Certainly, Mr Patel. We will send the confirmation to your email address."],["N","That is the end of part one."]],"instructions":"Questions 1–10. Complete the booking details. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.","questions":[{"n":1,"prompt":"Customer surname: ________","answer":"Patel","why":"The customer spells P-A-T-E-L."},{"n":2,"prompt":"Type of workshop: ________","answer":"printmaking","why":"He chooses printmaking rather than painting."},{"n":3,"prompt":"Updated date: ________ May","answer":"19","why":"The previous 17 May date was changed to the 19th.","accept":["nineteenth"]},{"n":4,"prompt":"Introduction begins at ________ p.m.","answer":"6:40","why":"6:15 is door opening; 6:40 is the introduction.","accept":["6.40","six forty"]},{"n":5,"prompt":"Room: ________ Studio","answer":"Alder","why":"Alder replaces the original Birch Studio."},{"n":6,"prompt":"Student ticket price: £________","answer":"32","why":"Student price £32; standard £40 and online £35.","accept":["thirty two","thirty-two"]},{"n":7,"prompt":"Deposit payable now: £________","answer":"10","why":"Only £10 is payable immediately.","accept":["ten"]},{"n":8,"prompt":"Clothing requirement: closed ________","answer":"shoes","why":"Customers should wear closed shoes; tools are provided."},{"n":9,"prompt":"Nearest usable bus stop: ________","answer":"Market Square","why":"Museum Road pavement is temporarily closed."},{"n":10,"prompt":"Refund cancellation notice: ________ hours","answer":"72","why":"The current notice period is 72 rather than 48 hours.","accept":["seventy two","seventy-two"]}]},{"title":"Part 2 · Tour of the wetlands reserve","subtitle":"A guide explains the route, visitor rules and activity sites.","people":{"N":"Narrator","F":"Guide"},"lines":[["N","Part two. You will hear a guide speaking to visitors at a wetlands reserve. Look at questions eleven to twenty."],["F","Welcome to the East Mere Wetlands Reserve. I am your guide, Ruth. We will start from this visitor centre and walk towards the reedbed bird hide. That will be our first stop, before we visit the meadow."],["F","Some of you may have planned to use the timber walkway by the south pool. It is closed, not because of nesting birds or high water, but because the handrails are being repaired."],["F","I will show you how to use a telescope at the reedbed hide. The demonstration was originally announced for ten forty-five; it is now at eleven fifteen. At eleven thirty you can try the equipment yourselves."],["F","Photography and sketching are both welcome. However, please do not cycle on the narrow footpaths. Bikes can be left in racks outside the entrance."],["F","You may see ducks near the feeding platform. Please resist the temptation to give them bread. The wrong food can affect the birds’ health and what remains in the water can damage water quality."],["F","Now, you might be interested in the activities taking place at different locations. At Orchard Bank, volunteers are counting butterflies and recording the flowers they visit."],["F","At the Old Pump House, a local historian will describe the machinery that once kept these fields dry. It is an introduction to the site’s industrial history rather than a practical repair class."],["F","The North Meadow has a wildflower identification walk. Staff will help you recognise several plants using their leaves and flowers."],["F","At River Bend, scientists will demonstrate how they collect small water samples and why they test their quality."],["F","Finally, the Education Shed is offering map-making for children and adults. You will create a simple map of the paths we are using."],["F","There is no bird-ringing demonstration today, although it sometimes appears in our seasonal programme."],["F","The path back to the visitor centre takes about fifteen minutes. Please stay with the group until we reach the bridge."],["N","That is the end of part two."]],"instructions":"Questions 11–15: Choose A, B or C. Questions 16–20: Choose the correct activity letter A–F for each place. ONE activity will not be used.","questions":[{"n":11,"prompt":"Where will the guided walk stop first?","answer":"B","why":"The first stop after the visitor centre is the reedbed bird hide.","choices":["A. North Meadow","B. Reedbed bird hide","C. Old Pump House"]},{"n":12,"prompt":"Why is the timber walkway closed?","answer":"B","why":"The guide explicitly rules out nesting birds and high water.","choices":["A. Birds are nesting nearby","B. The handrails are being repaired","C. The water level is too high"]},{"n":13,"prompt":"When does the telescope demonstration begin?","answer":"B","why":"10:45 was the earlier time; 11:30 is independent practice.","choices":["A. 10:45","B. 11:15","C. 11:30"]},{"n":14,"prompt":"Which visitor activity is not allowed on the paths?","answer":"A","why":"Cycling is prohibited on the narrow paths.","choices":["A. Cycling","B. Photography","C. Sketching"]},{"n":15,"prompt":"What is the main reason for not feeding the ducks?","answer":"C","why":"Food can harm duck health and water quality.","choices":["A. The ducks might attack visitors","B. Feed is sold at the centre","C. It can harm the birds and water"]},{"n":16,"prompt":"Orchard Bank: choose the activity.","answer":"A","why":"Orchard Bank hosts a butterfly count.","choices":["A. Butterfly survey","B. Industrial history","C. Wildflower identification","D. Water sampling","E. Map-making","F. Bird ringing"]},{"n":17,"prompt":"Old Pump House: choose the activity.","answer":"B","why":"The historian describes the former machinery.","choices":["A. Butterfly survey","B. Industrial history","C. Wildflower identification","D. Water sampling","E. Map-making","F. Bird ringing"]},{"n":18,"prompt":"North Meadow: choose the activity.","answer":"C","why":"North Meadow is for identifying wildflowers.","choices":["A. Butterfly survey","B. Industrial history","C. Wildflower identification","D. Water sampling","E. Map-making","F. Bird ringing"]},{"n":19,"prompt":"River Bend: choose the activity.","answer":"D","why":"River Bend has water sampling demonstrations.","choices":["A. Butterfly survey","B. Industrial history","C. Wildflower identification","D. Water sampling","E. Map-making","F. Bird ringing"]},{"n":20,"prompt":"Education Shed: choose the activity.","answer":"E","why":"The Education Shed hosts map-making.","choices":["A. Butterfly survey","B. Industrial history","C. Wildflower identification","D. Water sampling","E. Map-making","F. Bird ringing"]}]},{"title":"Part 3 · Researching student travel","subtitle":"Two students meet their supervisor to refine a campus transport survey.","people":{"N":"Narrator","F":"Supervisor","M":"Noah","W":"Priya"},"lines":[["N","Part three. You will hear two university students discussing a research project with their supervisor. Look at questions twenty-one to thirty."],["M","Dr Ellis, Priya and I have drafted a survey on how students travel to campus. We hoped to show that the new bus routes have improved journeys."],["F","Be careful. Your opening question says, “How much has the excellent new bus service helped you?” That assumes the bus service is excellent. It is a leading question."],["W","So we should ask something neutral, such as, “Which transport method do you use most often?”"],["F","Exactly. You also suggested asking your classmates to respond. That would be convenient but may exclude students from other faculties."],["M","Would a random selection of students from several faculties be better?"],["F","Yes. Try to include different faculties rather than relying on friends or people who volunteer at the sports centre."],["W","We thought a single question about average journey time would be sufficient."],["F","People often guess badly when asked for their typical travel time. Ask a smaller sample to keep a travel diary, recording each journey after it happens."],["M","We were going to run the study in the examination week because more students will be on campus."],["F","Examinations can change travel patterns. Collect the main survey in the middle of term, when routines are more typical."],["W","And for our analysis, should we simply calculate the mean journey time?"],["F","Report the median as your principal summary, because a few exceptionally long journeys could pull the mean upward. You can still include the mean for comparison."],["M","Before the survey, how many people should try our questions in a pilot?"],["F","A pilot with twelve students should be enough to identify confusing wording. It is not intended to test your full hypothesis."],["W","And the travel diary, should that run for a whole fortnight?"],["F","Five days will be more manageable. Make sure it includes normal teaching days."],["M","Perhaps we should ask whether respondents also have part-time jobs, since those may change when they leave campus."],["F","Good idea. That is a potentially important variable. And make sure the data are stored in an encrypted folder, not a shared public spreadsheet."],["W","Finally, should our report just present the main chart and the conclusion?"],["F","No. Include a section on limitations. For example, a five-day diary may not capture unusual journeys or holiday schedules."],["M","That gives us a much clearer plan. Thank you."],["N","That is the end of part three."]],"instructions":"Questions 21–25: Choose A, B or C. Questions 26–30: Complete the research notes with NO MORE THAN TWO WORDS AND/OR A NUMBER.","questions":[{"n":21,"prompt":"What is the supervisor’s first criticism of the survey?","answer":"A","why":"Calling the service “excellent” makes the question leading.","choices":["A. One question suggests a preferred answer","B. It has too many questions","C. It does not ask about bicycle use"]},{"n":22,"prompt":"Which approach to choosing participants is preferred?","answer":"A","why":"The supervisor wants representation from different faculties.","choices":["A. Randomly select students across faculties","B. Ask only classmates","C. Recruit from the sports centre"]},{"n":23,"prompt":"Why does the supervisor recommend a travel diary?","answer":"C","why":"A diary records journeys soon after they happen.","choices":["A. It removes the need for a survey","B. It makes all journeys equally long","C. It reduces errors caused by guessing travel time"]},{"n":24,"prompt":"When should the main survey take place?","answer":"B","why":"Examination week could alter ordinary commuting patterns.","choices":["A. During examination week","B. In the middle of term","C. During university holidays"]},{"n":25,"prompt":"Which statistic should be the principal summary of travel time?","answer":"B","why":"The median is less affected by a few extremely long journeys.","choices":["A. The largest journey time","B. The median journey time","C. The mean journey time"]},{"n":26,"prompt":"Pilot survey participants: ________","answer":"12","why":"The supervisor specifies twelve pilot participants.","accept":["twelve"]},{"n":27,"prompt":"Travel diary duration: ________ days","answer":"5","why":"A five-day diary is recommended over a fortnight.","accept":["five"]},{"n":28,"prompt":"Ask students whether they have ________ jobs.","answer":"part-time","why":"Part-time jobs may affect when students travel.","accept":["part time"]},{"n":29,"prompt":"Store survey data in an ________ folder.","answer":"encrypted","why":"The supervisor says to use an encrypted folder."},{"n":30,"prompt":"The final report must discuss its ________.","answer":"limitations","why":"The supervisor requires a limitations section."}]},{"title":"Part 4 · Why cities become hotter","subtitle":"A lecture on urban heat islands and how neighbourhoods can adapt.","people":{"N":"Narrator","M":"Lecturer"},"lines":[["N","Part four. You will hear part of an academic lecture on the urban heat island effect. Look at questions thirty-one to forty."],["M","Today we will examine why a city can remain warmer than the countryside around it. This pattern is called the urban heat island effect. It varies according to the weather, the built environment and the time of day."],["M","One starting point is the surface itself. Dark roads and roofs absorb a larger share of incoming solar radiation than many lighter surfaces. They can become very hot in sunshine."],["M","Some construction materials store energy during the day and release it later. Concrete, for example, can contribute to warmth after sunset, when people expect the air to cool."],["M","Vegetation changes the picture. The tree canopy provides shade for people and for the ground beneath it. When canopy cover is sparse, pedestrians can be exposed to more direct sunlight."],["M","Plants can also cool the air through evapotranspiration. For this process to work effectively, plants need available moisture. A green space with extremely dry soil may provide much less evaporative cooling."],["M","Engineers have experimented with lighter, reflective roof coatings. A suitable coating can reduce the amount of solar energy absorbed by a roof, although the result depends on the building and local climate."],["M","The shape of streets matters as well. Closely spaced high buildings can form what researchers call street canyons. These influence sunlight, airflow and the movement of heat."],["M","We need reliable measurements before comparing neighbourhoods. Weather sensors should not be placed directly against a hot wall. They are often housed in ventilated shelters, which reduce distortions from direct sunlight."],["M","The consequences of urban heat are not shared equally. Household income can influence whether residents have access to insulation, air conditioning or cooler housing. Age and health are also important, but income is one social indicator that planners frequently examine."],["M","A good response is not just to plant isolated trees. Cities can create connected green corridors so shade and vegetation extend along walking routes. These routes can be more useful than a few scattered patches."],["M","Finally, evaluating a project requires patience. We should monitor local temperatures over several years, because a single warm afternoon cannot tell us whether an intervention has succeeded."],["M","The key message is that both physical design and social conditions matter when we attempt to make cities safer during hot weather."],["N","That is the end of part four and the end of the listening test."]],"instructions":"Questions 31–40. Complete the lecture notes. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"prompt":"Dark roads absorb more solar ________.","answer":"radiation","why":"Dark surfaces absorb incoming solar radiation."},{"n":32,"prompt":"A building material that releases heat after sunset: ________.","answer":"concrete","why":"Concrete is the specific material mentioned."},{"n":33,"prompt":"The tree ________ provides shade.","answer":"canopy","why":"The lecturer identifies tree canopy cover."},{"n":34,"prompt":"Effective evaporative cooling needs available ________.","answer":"moisture","why":"Dry soil limits evapotranspiration."},{"n":35,"prompt":"Reflective roof ________ can reduce absorbed sunlight.","answer":"coatings","why":"The speaker describes reflective roof coatings.","accept":["coating"]},{"n":36,"prompt":"Closely spaced buildings create street ________.","answer":"canyons","why":"The academic term is street canyons.","accept":["canyon"]},{"n":37,"prompt":"Weather sensors are placed in ventilated ________.","answer":"shelters","why":"Ventilated shelters reduce direct-sun measurement problems.","accept":["shelter"]},{"n":38,"prompt":"A social factor influencing access to cooler homes: ________.","answer":"income","why":"Household income is named as an indicator."},{"n":39,"prompt":"Connected green ________ can improve walking routes.","answer":"corridors","why":"The lecturer prefers connected green corridors.","accept":["corridor"]},{"n":40,"prompt":"Projects should monitor local ________ over several years.","answer":"temperatures","why":"Long-term monitoring of temperatures is recommended.","accept":["temperature"]}]}],"extreme":{"title":"IELTS Listening — Extreme Challenge (Original Practice Test)","sections":[{"title":"Part 1 — Wetland Conservation Booking","context":"A telephone conversation between a prospective volunteer and the coordinator of a conservation programme.","speakers":{"N":"Narrator","M":"Coordinator — British woman","J":"Caller — Australian man"},"lines":[["N","You will hear a telephone conversation about a volunteer induction at a wetland conservation centre. First, you have some time to look at questions one to ten. Now listen carefully and answer questions one to ten."],["M","Good afternoon, East Vale Wetland Trust. Megan speaking. How may I help?"],["J","Hi, I’m calling about the photography project for volunteers. I think the website calls it the Riverside scheme?"],["M","You’re very close. Riverside was last year’s exhibition. The one we’re recruiting for now is called Riverlight. It’s one word: Riverlight. You’d be helping us record changes in the reed beds."],["J","Riverlight. Right. I saw an orientation on the fourteenth of March. Is that still going ahead?"],["M","The fourteenth is still on our old leaflet, I’m afraid. We moved it because the site manager is away. The induction is now on the seventeenth of March, and there won’t be a session on the fourteenth."],["J","Okay, seventeenth. Is that at a quarter past nine?"],["M","That was the original arrival time. We now ask everyone to meet at eight forty-five, although the actual safety briefing doesn’t begin until nine fifteen. You’ll want to be there at eight forty-five to collect your badge."],["J","And I go to the visitors’ centre as usual?"],["M","Not for this session. There are two entrances and it’s surprisingly easy to end up at the wrong one. Please go straight to Orchard Gate. That’s where the volunteers meet. The main visitors’ centre won’t be open that early."],["J","I’m taking a camera and a tripod. Will I need my own protective gear?"],["M","We can lend you a waterproof jacket and we supply gloves. Boots are the only thing you must bring yourself; ankle boots are fine if they’re waterproof. Don’t bother purchasing specialist gloves."],["J","How long is the first activity? I might need to leave by lunchtime."],["M","The outdoor survey lasts ninety minutes, after which there’s an optional editing workshop. Some people read that the whole induction is three hours, but only the survey is compulsory."],["J","And how much does it cost? A friend mentioned twenty pounds."],["M","There isn’t a twenty-pound joining fee. You pay a twelve-pound equipment deposit when you register. It’s refunded once you return the equipment in good condition. If you choose the afternoon workshop, that’s a separate eight pounds."],["J","That sounds fair. I don’t drive. Can I catch the two-oh-four bus?"],["M","Yes, that’s the one. Take route two hundred and four to the old library, then walk for about seven minutes. The two hundred and forty goes past the centre, but it stops on the other side of the river and the footbridge is closed."],["J","Do you need a passport or driving licence for identification?"],["M","If you’re currently at a university, just bring your student card. We prefer that for the student rate. You don’t need a passport. Otherwise, ordinary photographic identification is fine."],["J","And if I have to cancel, can I ring the day before?"],["M","Please give us forty-eight hours’ notice. We previously said twenty-four, but our volunteers now prepare the equipment two days beforehand. Cancelling later means we may keep the deposit."],["J","Could you send the confirmation by post as well as email? My postcode’s B R three, eight L T."],["M","Let me read that back: B R three, eight L T. Not B R eight?"],["J","No, the first number is three. B R three, space, eight L T."],["M","Lovely. I’ve got it. We’ll send the details later today, and the meeting point will be printed in bold so you don’t accidentally go to the wrong gate."],["N","That is the end of Part One. You have half a minute to check your answers."]]},{"title":"Part 2 — Harbour Science Museum Orientation","context":"A museum education officer describes the floor plan and explains the programme for visiting students.","speakers":{"N":"Narrator","G":"Guide — British man"},"lines":[["N","You will hear a museum education officer introducing the Harbour Science Museum to a group of visitors. Look at the plan and questions eleven to twenty. Now listen and answer questions eleven to twenty."],["G","Welcome to the Harbour Science Museum. You should have the small plan printed at the top of your question sheet. The entrance is at the bottom, on the south side, and you come into the reception space marked E. The plan is not quite to scale, which is why I’m going to describe it carefully."],["G","Let me begin with the lower row. If you come in through the entrance and turn left, before you reach the staircase, you’ll find the equipment loan counter. That’s the room immediately west of reception. It used to sell tickets; tickets are now digital, so please ignore the old sign above the door."],["G","Now, on the opposite side of reception, in the lower-right corner, is the repair studio. It is a working space where our technicians restore scientific instruments. That used to be a small café, and the café has moved upstairs; the studio is only visible through its internal window."],["G","The upper row is a little more confusing. The large room directly north of reception is the listening gallery. It has recordings of harbour workers and underwater soundscapes. Although the room is sometimes called the sound laboratory in brochures, the sound laboratory proper is in another building."],["G","To the east of that gallery is our specimen room, at the north-eastern end of the corridor. You won’t be allowed to handle the materials, but you can view them from the observation line. Years ago that room held the museum library, but the specimens were moved there to keep humidity stable."],["G","Finally, the quiet reading room is in the north-west corner, on the other side of the listening gallery. You might assume it’s next to the repair studio because the names sound related, but they’re on diagonally opposite sides of this level."],["G","I want to emphasise something about the order of activities. Your first booked event is the tidal-energy demonstration at ten thirty. The printed programme still says ten fifteen, but that refers to staff preparation. Please don’t arrive at ten fifteen and expect to see the demonstration."],["G","There’s also a fascinating exhibition on old navigation systems. The bronze compass behind the entrance is a reproduction. The original is in storage, not because it was stolen or damaged, but because repeated exposure to strong light began to affect its surface. We have not yet found a display case we’re happy with."],["G","For the listening gallery you’ll be given headphones. You can use them for up to twenty minutes at a time, not because of a hearing risk, but to make sure everybody gets a turn. We have limited sets. If your session is full, you’ll be asked to rejoin the queue."],["G","Students often ask if they can photograph the collection for their assignments. Ordinary photography is permitted in most of the building. However, do not use flash in the specimen room: it interferes with the sensors. Photography itself isn’t prohibited there, and tripods are simply not practical in the narrow walkway."],["G","This afternoon we have three talks, and you should choose the one most relevant to your coursework. At one o’clock, a marine historian will explain how shipping records can reveal long-term weather patterns. At two, an engineer will talk about the design of tidal turbines, including their effect on wildlife. At three thirty, a curator will discuss why oral histories can contradict official documents."],["G","If your research is about how people remember coastal events, I’d recommend the three thirty talk, rather than the historian’s session. If you need performance data about energy technology, the two o’clock talk is the obvious choice."],["G","One final practical matter. If you leave anything behind, speak to reception rather than the security desk by the car park. Reception records found items each evening, while the security desk deals with access and lost visitor passes. The arrangements are rather different from what the online visitor guide suggests."],["G","Before we move on, I’ll give you a minute to study the floor plan again. You can see why a room’s former purpose is not a reliable guide to where it is today."],["N","That is the end of Part Two. You have half a minute to check your answers."]]},{"title":"Part 3 — Designing a Research Study","context":"Two postgraduate students discuss a pilot experiment with their supervisor.","speakers":{"N":"Narrator","L":"Leila — British woman","T":"Tom — Australian man","P":"Professor — British man"},"lines":[["N","You will hear two postgraduate students, Leila and Tom, meeting their supervisor to discuss the design of a research project. Look at questions twenty-one to thirty. Now listen carefully."],["P","So, you’ve sent me the proposal on urban noise and working memory. I can see you’ve done a lot of reading, but I’m not entirely convinced by the design. Could you summarise it?"],["L","We planned to recruit thirty volunteers from the commuter network. Half would work for forty minutes in a quiet room, and the others would complete the same tasks with recorded traffic noise. Afterwards we’d compare their scores."],["T","We were going to let them choose which condition they preferred, since some people find silence quite uncomfortable."],["P","And that is your first major problem. If participants choose the condition, the groups might differ before the experiment even starts. People who are already particularly sensitive to noise could all select the quiet room. You’d be measuring a pre-existing difference as much as the effect of the sound."],["L","So random assignment? We had worried that would upset them."],["P","Random assignment, with the option to withdraw. That doesn’t remove every source of bias, but it stops preference from determining the comparison groups. Don’t confuse ethical choice to withdraw with choosing the experimental condition."],["T","I wondered if we could improve the quiet room by soundproofing it completely."],["P","Not necessarily. Absolute silence is itself unusual, and then you’d be testing two extremes rather than typical working environments. Better to keep lighting, temperature and seating as closely matched as possible, and use a low, consistent background level in the quieter condition."],["L","We thought of playing the sound from participants’ phones because it would be cheaper."],["T","But the recordings sound different on each phone, even when the volume slider shows the same level. Some devices cut out much of the low-frequency traffic rumble, so we’d lose the very component we want to investigate."],["P","Exactly. Use identical external speakers and check the measured sound levels, not just the number on the volume control. A recording that seems equally loud to one person may have a very different frequency profile."],["L","For the task, our first idea was to look at how quickly people press a button when a colour changes."],["P","Reaction speed might be informative as a secondary measure, but it doesn’t directly test your claim about remembering information. I’d much rather see delayed recall: present the material, introduce a short unrelated activity, and then measure how much they remember."],["T","What about immediate recall as well?"],["P","You can include it, but make delayed recall your principal outcome before you collect any data. Otherwise it’s all too tempting to favour whichever measure happens to give a dramatic result."],["L","So the pilot is to see whether the procedure works, rather than to prove our hypothesis."],["P","Precisely. Your pilot should last six weeks, not the ten you originally requested. Six is enough to assess whether recruitment, equipment and the test sequence are practical. It won’t provide a definitive estimate of a population-wide effect."],["T","I had suggested a convenient sample of students from our department."],["P","And that would be easy, but your research question is about the experience of commuters. I want your pilot participants to be commuters, even if you begin with only a modest number. Don’t describe a sample of students as representative of urban travellers."],["L","We’ll collect some background information. Age, the length of their journey, how often they work remotely ..."],["P","Those could be useful, but what about sleep? Someone who slept badly may perform worse on the recall test regardless of the noise. Ask about the previous night’s sleep, and be careful not to turn the questionnaire into an exhausting task in itself."],["T","Should we ask them how irritating they found the noise?"],["P","Yes, as a subjective rating. But you must also record the actual levels in decibels. The two measures answer different questions: annoyance is a personal judgement, while the sound meter gives you a repeatable physical reading."],["L","We’ve drafted an analysis section comparing the average scores in each group. We could present a graph with a single headline difference."],["P","Include the comparison, certainly, but I’d like the report to give confidence intervals as well. A difference of five points sounds impressive until you discover the plausible range is extremely wide. The intervals will force you to acknowledge what the pilot can and cannot tell you."],["T","We can also run several extra tests to see which subgroup responds most."],["P","You may explore patterns, but please pre-register your main outcome and exclusion rules before collecting data. If someone is removed because their equipment failed, document it. Do not decide afterwards that low scorers should be excluded simply because that makes the results look tidier."],["L","Understood. We’ll specify the primary outcome, use random assignment, and make the physical conditions comparable. And we’ll be transparent if the pilot remains inconclusive."],["P","Good. Inconclusive is not a synonym for unsuccessful. A well-designed pilot tells you whether a larger study is worth undertaking. A poorly designed one gives you a confident answer to the wrong question."],["N","That is the end of Part Three. You have half a minute to check your answers."]]},{"title":"Part 4 — Restoring Coastal Salt Marshes","context":"A lecture on blue carbon, marsh restoration, and the challenges of measuring environmental benefits.","speakers":{"N":"Narrator","A":"Lecturer — British woman"},"lines":[["N","You will hear part of a university lecture about coastal salt marsh restoration. Look at questions thirty-one to forty. Now listen and answer questions thirty-one to forty."],["A","Today I want to examine a claim that is appearing more and more often in environmental policy: that restoring salt marshes is an unusually efficient way to remove carbon from the atmosphere. There is a real scientific basis for this claim, but it is also easy to exaggerate. My argument is not that the benefits are imaginary; it is that they have to be measured in a way that acknowledges what we still do not know."],["A","First, what exactly is a salt marsh? It is a low-lying coastal area regularly flooded by seawater, with plants adapted to saline conditions. These plants draw carbon dioxide from the air as they grow. Much of the carbon ultimately enters the sediment below them, where waterlogged conditions can slow decomposition. The striking feature is that the carbon may remain buried for a very long time, provided the sediment is not disturbed."],["A","That gives us our first misconception. People tend to compare restored marshes using the number of hectares planted. But area alone cannot tell us whether the habitat will survive. The elevation of the marsh surface relative to sea level is crucial. If the surface sits too low, young plants may be submerged for too long. If it is too high, seawater may hardly reach it, and you may end up with an entirely different ecosystem."],["A","The next issue is water movement. Historically, many marshes were drained for grazing, farming or housing. Engineers blocked the creeks or built embankments, interrupting the tides that would ordinarily bring water and sediment in and out. Reopening a channel can therefore matter more than planting hundreds of seedlings. Indeed, the return of natural tidal exchange is often one of the first signs of functional recovery."],["A","However, restoration can involve a temporary cost that rarely appears in promotional brochures. When previously drained soils become wet again, microbial conditions change. Methane, a powerful greenhouse gas, may be released, particularly where the water is relatively fresh. It would be misleading to count the carbon stored by plants while ignoring the gases released from the soil. The balance depends on salinity, temperature and management over time."],["A","This brings us to the idea of a baseline. Suppose a site had been deteriorating for decades before the restoration began. If we compare today’s carbon stock with a neighbouring healthy marsh, we could underestimate the improvement. But if we assume that every tonne stored after restoration is an additional benefit, we may overestimate it. Scientists need a defensible baseline: an account of what would probably have happened without the intervention."],["A","So how do we measure carbon? One method involves taking narrow vertical samples called sediment cores. Scientists analyse the layers to estimate how much organic material has accumulated and, with suitable dating methods, how quickly it was buried. This is informative, but collecting a core from one position does not necessarily represent an entire marsh. Channels, vegetation and soil density vary enormously over short distances."],["A","For larger areas, satellites allow researchers to map changes in vegetation and shoreline position across many years. But a satellite cannot directly tell us how much carbon lies deep underground. That information still depends on field sampling and laboratory analysis. Remote sensing and direct measurement should therefore be treated as complementary rather than interchangeable approaches."],["A","There is also the question of durability. A site can absorb carbon for several years and then release part of it if a storm removes the underlying material. Erosion is an especially important risk on exposed coasts, although well-established marsh vegetation can sometimes reduce wave energy and protect the shore. When a carbon project promises permanent storage, we should ask what monitoring will continue after the initial funding ends."],["A","Fortunately, carbon is not the only reason to restore these habitats. Salt marshes provide nurseries for young fish, support migratory birds and, in some locations, reduce flooding in nearby settlements by slowing the movement of storm water. The extent of that protection varies with the width and condition of the marsh. It should not be treated as a substitute for every engineered flood defence, but it can be a valuable part of a wider strategy."],["A","An economic assessment complicates matters further. Some advantages, such as improved fisheries or avoided flood damage, may be expressed in monetary terms. Others, including cultural attachment to a coastal landscape, are much harder to price. A decision that counts only the carbon value will often miss the reasons local communities support, or oppose, a project. Engagement with residents is not merely a matter of public relations; it can identify consequences overlooked in the initial design."],["A","Let me end with a practical principle. Good environmental reporting should not offer a single precise number when the evidence cannot justify it. Report ranges for expected carbon benefits, state the assumptions used to calculate them, and explain how the findings might change under rising sea levels or different storm patterns. A range is not an admission that science has failed. It is a way of communicating uncertainty responsibly, which is essential if restoration is to earn long-term public trust."],["N","That is the end of Part Four. You now have time to check your answers. The listening test is finished."]]}],"questions":[["Part 1","Questions 1–10: Complete the booking notes. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.",[[1,"Current project name: __________"],[2,"Revised induction date: __________ March"],[3,"Volunteer arrival time: __________"],[4,"Meeting entrance: __________ Gate"],[5,"Protective item supplied by the trust: __________"],[6,"Length of compulsory outdoor survey: __________ minutes"],[7,"Refundable equipment deposit: £__________"],[8,"Bus route recommended: __________"],[9,"Cancellation notice required: __________ hours"],[10,"Postcode: __________"]]],["Part 2","Questions 11–15: Label the plan. Choose the correct letter, A–F, for each location. Questions 16–20: Choose the correct answer, A, B or C.",[[11,"Equipment loan counter: ____"],[12,"Repair studio: ____"],[13,"Listening gallery: ____"],[14,"Specimen room: ____"],[15,"Quiet reading room: ____"],[16,"When will the tidal-energy demonstration begin?\n A. 10:15\n B. 10:30\n C. 10:45"],[17,"Why is the original bronze compass not on display?\n A. It was damaged by a visitor.\n B. A theft investigation is ongoing.\n C. Its surface was being affected by light."],[18,"Why is the use of headphones time-limited?\n A. There are too few sets.\n B. They may cause hearing damage.\n C. They need frequent recharging."],[19,"What restriction applies in the specimen room?\n A. No photography of any kind.\n B. No flash photography.\n C. No mobile telephones."],[20,"Which afternoon talk is best for someone studying personal recollections of coastal events?\n A. 1:00 p.m.\n B. 2:00 p.m.\n C. 3:30 p.m."]]],["Part 3","Questions 21–25: Choose the correct answer, A, B or C. Questions 26–30: Complete the notes. Write NO MORE THAN TWO WORDS AND/OR A NUMBER.",[[21,"What is the supervisor’s main criticism of the original group allocation?\n A. The sample size is too large.\n B. Participants’ preferences could create unequal groups.\n C. Participants would be unable to withdraw."],[22,"How should the researchers set up the quieter condition?\n A. Eliminate all background sound.\n B. Allow participants to choose the conditions.\n C. Maintain comparable physical conditions and low, steady noise."],[23,"Why do they reject using participants’ mobile phones?\n A. Phones may fail to reproduce low-frequency sound consistently.\n B. Most phones cannot play recorded sound.\n C. Participants could see the answers on their screens."],[24,"Which measure should be the principal research outcome?\n A. Button-press reaction time.\n B. Delayed recall.\n C. Immediate recall."],[25,"What does the supervisor insist they do before collecting data?\n A. Remove all participants with low scores.\n B. Add more exploratory tests.\n C. Register their main outcome and exclusion rules."],[26,"Pilot duration: __________"],[27,"Target participant group: __________"],[28,"Background variable related to the previous night: __________"],[29,"Physical sound levels should be recorded in: __________"],[30,"The results report should include: __________"]]],["Part 4","Questions 31–40: Complete the lecture notes. Write ONE WORD ONLY for each answer.",[[31,"Much of the captured carbon is stored in the __________ beneath marsh plants."],[32,"The __________ of the marsh relative to sea level affects the survival of plants."],[33,"Restoration may involve reopening channels to restore natural __________."],[34,"Re-wetting soil can sometimes lead to emissions of __________."],[35,"Researchers must establish a credible __________ for comparison."],[36,"Vertical samples of marsh material are known as sediment __________."],[37,"Changes in vegetation over large areas can be mapped using __________."],[38,"Storm-related __________ can threaten long-term carbon storage."],[39,"A wider benefit of marshes is reducing coastal __________."],[40,"Instead of a single precise estimate, reports should present __________."]]]],"answers":{"1":"Riverlight","2":"17","3":"8:45","4":"Orchard","5":"gloves","6":"90","7":"12","8":"204","9":"48","10":"BR3 8LT","11":"D","12":"F","13":"B","14":"C","15":"A","16":"B","17":"C","18":"A","19":"B","20":"C","21":"B","22":"C","23":"A","24":"B","25":"C","26":"six weeks","27":"commuters","28":"sleep","29":"decibels","30":"confidence intervals","31":"sediment","32":"elevation","33":"tides","34":"methane","35":"baseline","36":"cores","37":"satellites","38":"erosion","39":"flooding","40":"ranges"},"explanations":{"1":"Riverside was an old exhibition; Riverlight is the current programme.","2":"The leaflet says 14 March, but the induction was moved to the 17th.","3":"8:45 is arrival; 9:15 is only the briefing.","4":"Orchard Gate is the meeting point, not the visitors’ centre.","5":"Gloves are supplied; you must bring your own boots.","6":"The survey lasts ninety minutes; the later workshop is optional.","7":"£12 is the refundable deposit; £8 is a separate workshop fee.","8":"The 204 works; the 240 stops beyond a closed footbridge.","9":"The old 24-hour policy was replaced with 48 hours.","10":"The caller explicitly corrects the first number: BR3 8LT.","11":"Left/west of central E on the lower row is D.","12":"Opposite the loan counter, bottom-right, is F.","13":"Directly north of reception E is B.","14":"East of the central gallery, top-right, is C.","15":"The top-left/north-west corner is A.","16":"10:15 is staff preparation; the actual start is 10:30.","17":"Light exposure, not theft or accidental breakage, is the problem.","18":"The number of available headsets, not safety, determines the limit.","19":"Photography is fine but the flash disrupts sensors.","20":"The curator’s 3:30 talk discusses oral histories and conflicting records.","21":"Voluntary choice could create two groups that differ before testing.","22":"Absolute silence would be unrealistic; conditions should be matched.","23":"Different phone speakers lose low-frequency rumble to different extents.","24":"The supervisor calls delayed recall the principal measure.","25":"Pre-registration prevents inventing exclusions after seeing the results.","26":"Six weeks replaces their original ten-week request.","27":"Commuters, rather than the convenient students, match the research question.","28":"Poor sleep could reduce test scores independently of noise.","29":"Decibels are the measured sound levels, separate from perceived annoyance.","30":"Confidence intervals communicate the plausible range of the effect.","31":"Carbon accumulates below the plants in the sediment.","32":"A marsh too high or low will change how often it is submerged.","33":"Restoration may restore the flow of tides through reopened channels.","34":"Microbes in rewetted soils may produce methane.","35":"A baseline describes what would have happened without restoration.","36":"Sediment cores are narrow vertical samples used to estimate burial.","37":"Satellites track changes in vegetation and shoreline position.","38":"Erosion can remove carbon-rich marsh material after storms.","39":"Marshes can slow storm water and lower local flooding risk.","40":"The lecturer advocates ranges rather than one unsupported exact value."}}},"writing":{"easy":{"slug":"easy","level":"Easy","t1lead":"The bar chart below shows the number of books borrowed, in thousands, from three sections of a city library in 2019 and 2024.","t1instruction":"Summarise the information by selecting and reporting the main features, and make comparisons where relevant.","t2question":"Some people believe that schools should teach children how to manage money. To what extent do you agree or disagree?","data":"2019: Fiction 40k; Non-fiction 25k; Children’s 20k. 2024: Fiction 55k; Non-fiction 30k; Children’s 35k."},"moderate":{"slug":"moderate","level":"Moderate","t1lead":"The line graph shows the proportion of commuters using a car, public transport or a bicycle to travel to work in the town of Westbridge between 2000 and 2025.","t1instruction":"Summarise the information by selecting and reporting the main features, and make comparisons where relevant.","t2question":"Some people believe that governments should invest more in public transport to reduce traffic congestion, while others think building new roads is the better solution. Discuss both views and give your own opinion.","data":"Years 2000, 2005, 2010, 2015, 2020, 2025. Car: 60,58,52,47,42,39%. Public transport: 25,27,31,34,37,39%. Bicycle: 15,15,17,19,21,22%."},"high":{"slug":"high","level":"High","t1lead":"The stacked bar chart shows electricity generated from four sources in the fictional region of Northmere in 2010, 2015, 2020 and 2025. The accompanying table gives total electricity consumption during the same years. All figures are in terawatt-hours (TWh).","t1instruction":"Summarise the information by selecting and reporting the main features, and make comparisons where relevant.","t2question":"As artificial intelligence performs a growing number of tasks previously done by people, some argue that governments should provide a universal basic income. Others believe public funds would be better spent on education and retraining. Discuss both views and give your own opinion.","data":"Sources in TWh by year 2010,2015,2020,2025: Coal 70,65,50,30; Gas 35,40,45,40; Wind 8,15,30,47; Solar 2,5,16,33. Totals 115,125,141,150. Consumption 110,123,145,160."}},"speaking":[{"id":"A","title":"Everyday Decisions","desc":"Studies, daily routines and advice","focus":"Advice and independent decisions","p1":[["Studies","Do you work or are you a student?"],["Studies","What do you enjoy most about what you study or do?"],["Studies","Is there something you find particularly challenging about it?"],["Studies","Would you like to do something similar in the future?"],["Daily routines","What is usually the busiest part of your day?"],["Daily routines","Do you prefer to plan your day carefully or be more spontaneous?"],["Daily routines","Has your daily routine changed since you were younger?"],["Technology","Which app on your phone do you use most often?"],["Technology","Do you sometimes try to spend less time on your phone?"],["Technology","Is there a new piece of technology you would like to learn to use?"]],"cue_title":"Describe a time when someone gave you advice that was useful.","cue":["who gave you the advice","what the advice was about","why you needed the advice","and explain how you felt after following it."],"follow":"Do you often ask other people for advice?","p3":[["Advice in society","Why do some people find it difficult to accept advice?"],["Advice in society","What makes someone a trustworthy person to ask for advice?"],["Generations","Do you think advice from older people is always more useful than advice from younger people?"],["Technology","How has the internet changed the way people make important decisions?"],["Education","Should schools teach students how to make difficult decisions?"],["Future","Do you think people will rely more on technology for personal advice in the future?"]]},{"id":"B","title":"Travel & Places","desc":"Hometown, free time and memorable journeys","focus":"Travel and the effect of tourism","p1":[["Hometown","Where is your hometown?"],["Hometown","What do you like most about living there?"],["Hometown","Has your hometown changed much in recent years?"],["Hometown","Do you think you will live there in the future?"],["Free time","What do you usually do at weekends?"],["Free time","Do you prefer spending time outdoors or indoors?"],["Free time","What did you enjoy doing in your free time as a child?"],["Travel","Do you often take short trips to nearby places?"],["Travel","What do you usually take with you when you go on a trip?"],["Travel","Is there a place in your country you would particularly like to visit?"]],"cue_title":"Describe a journey that you remember particularly well.","cue":["where you travelled and who you went with","how you travelled there","what happened during the journey","and explain why you remember it so clearly."],"follow":"Would you like to take the same journey again?","p3":[["Travel choices","Why do people sometimes prefer travelling by train rather than by plane?"],["Cities","What are the main transport problems facing large cities?"],["Environment","Should governments encourage people to use public transport more often?"],["Tourism","How can tourism benefit local communities?"],["Tourism","What problems can happen when too many tourists visit the same place?"],["Future","How might the way people travel change over the next twenty years?"]]},{"id":"C","title":"Skills & Learning","desc":"Learning habits, achievements and education","focus":"Education, skills and working life","p1":[["Learning","Do you enjoy learning new things?"],["Learning","What is something useful you have learned recently?"],["Learning","Do you prefer learning by yourself or with a teacher?"],["Learning","What subject did you find easiest at school?"],["Time","Are you usually good at managing your time?"],["Time","What do you do when you have several things to finish?"],["Time","Do you think you have more free time now than you did as a child?"],["Achievements","Do you like setting yourself personal goals?"],["Achievements","How do you usually celebrate when you achieve something?"],["Achievements","Is there a skill you hope to develop in the next few years?"]],"cue_title":"Describe a skill you learned that seemed difficult at first.","cue":["what the skill was","when and why you decided to learn it","how you practised it","and explain what changed when you became better at it."],"follow":"Do you still use that skill regularly?","p3":[["Learning methods","What are the main differences between learning from books and learning through experience?"],["Schools","Do schools place too much emphasis on examination results?"],["Motivation","Why do adults sometimes find it difficult to learn new skills?"],["Work","Which skills do you think employers value most today?"],["Technology","Will artificial intelligence make it easier or harder for people to learn independently?"],["Future","How might education change to prepare young people for jobs that do not exist yet?"]]}],"reading":{"easy":{"label":"Easy","minutes":60,"passages":[{"title":"Passage 1 · A Library for Seeds","paras":["In 2016, the town of Merriton opened a small seed library inside its public library. The idea was simple: residents could borrow packets of vegetable seeds, grow the plants at home and return a portion of the seeds they collected. Unlike a conventional book loan, there was no fine if a crop failed. Organisers wanted beginners to feel welcome rather than worry about making mistakes.","The project began with five volunteers who sorted donated seeds into paper envelopes. Each envelope carried a label showing the plant name, the likely growing season and short instructions. The volunteers also created a catalogue so people could find seeds without opening every envelope. Most borrowing takes place in spring, although some crops can be planted later.","The library now offers workshops on watering, saving seeds and caring for soil. Children often attend with their families. During one workshop, visitors compared soil kept under dry leaves with uncovered soil and learned why a layer of mulch can reduce the loss of water. In another session, an experienced gardener explained how to identify seeds that had not dried properly.","The project has changed in response to warmer summers. Recently the volunteers have placed greater emphasis on varieties that tolerate drought. They still encourage residents to grow crops they enjoy eating, rather than choosing a plant only because it is popular on social media.","Although the project is located inside a public library, it is run independently from the book-lending system. Its organisers are now discussing a small outdoor demonstration garden. A final decision has not been made, because the proposed site has limited sunlight."],"questions":[{"type":"short","prompt":"In which year did the seed library open?","answer":"2016","why":"The first paragraph gives the opening year."},{"type":"short","prompt":"Where inside the town is the seed library located?","answer":"public library","why":"The project opened inside the public library."},{"type":"short","prompt":"How many volunteers started the project?","answer":"five","why":"Five volunteers organised the initial donations."},{"type":"short","prompt":"The seeds were originally placed in paper ________.","answer":"envelopes","why":"The seeds were sorted into paper envelopes."},{"type":"short","prompt":"What helped borrowers find seeds without opening packets?","answer":"catalogue","why":"The volunteers created a catalogue."},{"type":"short","prompt":"During which season does most borrowing happen?","answer":"spring","why":"Most borrowing takes place in spring."},{"type":"short","prompt":"A layer of ________ helps reduce water loss from soil.","answer":"mulch","why":"The workshop covered the water-saving benefits of mulch."},{"type":"short","prompt":"New seed varieties are chosen partly for their tolerance of ________.","answer":"drought","why":"The library increasingly selects drought-tolerant varieties."},{"type":"tfn","prompt":"A failed harvest can result in a fine.","answer":"FALSE","why":"The library does not charge a fine if crops fail.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Children sometimes join the gardening workshops.","answer":"TRUE","why":"Children often attend with their families.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The outdoor demonstration garden has already been approved.","answer":"FALSE","why":"A final decision on the garden has not been made.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"Why did organisers decide not to fine people after crop failure?","options":["To encourage beginners","To increase seed prices","To reduce staff numbers","To sell vegetables"],"answer":"A","why":"They wanted beginners to participate without fear of mistakes."},{"type":"choice","prompt":"What is a current obstacle to the proposed outdoor garden?","options":["A lack of volunteers","Limited sunlight","A shortage of seeds","A high membership fee"],"answer":"B","why":"The possible site has limited sunlight."}]},{"title":"Passage 2 · Sharing Bicycles","paras":["In 2018, the small city of Lakehaven launched a bicycle-sharing programme with 12 stations near schools, parks and the railway station. Each bicycle could be unlocked through a mobile app. Visitors without a smartphone could borrow a temporary access card at the tourist office, but only during its normal opening hours.","The first 30 minutes of every journey were included in a basic membership. Riders paid an additional fee for longer trips. The programme used bright orange bicycles to make them easy to identify on busy streets. The city council chose this colour after testing several designs in a public survey.","Safety officers advised riders to wear a helmet, but the bicycles were not supplied with one. This confused some visitors, so signs at the stations now make the policy clearer. A group of local shops offers helmet rentals, although they operate independently of the bicycle scheme.","Data from the first two years showed that journeys were shortest during the morning rush hour and longer on weekends. Rainfall reduced overall demand, particularly among people making leisure trips. The council introduced a simple weather notice in the app, but it does not block bookings when rain is forecast.","Bicycles are inspected every week. Mechanics look closely at brakes, lights and tyre pressure. In 2021, the council added a repair workshop beside the central railway station to shorten the time that damaged bicycles remain out of use."],"questions":[{"type":"short","prompt":"When did the bicycle-sharing programme begin?","answer":"2018","why":"The launch year is 2018."},{"type":"short","prompt":"How many stations were available at launch?","answer":"12","why":"There were twelve stations initially."},{"type":"short","prompt":"Most users unlock bicycles through a mobile ________.","answer":"app","why":"The standard unlocking method is a mobile app."},{"type":"short","prompt":"A temporary card can be collected at the ________.","answer":"tourist office","why":"Visitors without smartphones can visit the tourist office."},{"type":"short","prompt":"The basic membership includes the first ________ minutes of each trip.","answer":"30","why":"The included period is thirty minutes."},{"type":"short","prompt":"What colour are the shared bicycles?","answer":"orange","why":"The bicycles are bright orange."},{"type":"short","prompt":"Which item of safety equipment must riders provide themselves?","answer":"helmet","why":"Helmets are advised but not supplied."},{"type":"short","prompt":"Bicycles are inspected every ________.","answer":"week","why":"Mechanics inspect bicycles each week."},{"type":"tfn","prompt":"Users must cancel their booking when rain is forecast.","answer":"FALSE","why":"The weather notice does not prevent bookings.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Trips tend to be longer at weekends.","answer":"TRUE","why":"Weekend journeys were reported as longer.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The bike scheme pays local shops to rent helmets.","answer":"NOT GIVEN","why":"The shops are independent; there is no information about payment to them.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"Why were the bicycles painted orange?","options":["To match the railway station","To make them easier to recognise","To hide damage to the frames","To advertise a sports team"],"answer":"B","why":"The colour improves visibility and identification."},{"type":"choice","prompt":"Why was a repair workshop added?","options":["To improve bicycle availability","To train schoolchildren","To sell old bicycles","To increase tourist-office hours"],"answer":"A","why":"The workshop reduces the period bicycles spend out of service."}]},{"title":"Passage 3 · Bees Above the City","paras":["Bees are important pollinators, moving pollen between flowers as they collect nectar. While many people imagine hives in rural fields, several species can also survive in cities. Some use small gardens; others visit flowering plants on rooftops and balconies. A research team at Bellfield University examined how insects moved between these places.","The team studied 24 rooftops over two summers. It recorded the flowering plants at each site and compared them with bee visits. Rooftops with a wide selection of flowers generally attracted more species than rooftops planted with only one kind. However, the researchers warned that flower diversity alone would not guarantee a healthy bee population.","Many urban bees are solitary, meaning that a female makes her own nest rather than living in a large colony. Some species use hollow stems, while others nest in the ground. Because their needs differ, a useful garden provides more than flowers. It also includes safe nesting places and avoids unnecessary pesticides.","City gardeners often plant decorative flowers that bloom for just a few weeks. The researchers recommended choosing plants that flower at different times from spring until autumn. They also favoured native plants where these are suitable, because local insects are already adapted to them.","One unexpected result was that connected patches of greenery appeared to be more useful than isolated large pots. The team called these connections green corridors. The results have encouraged several schools to plan small linked gardens, although the researchers have not yet tested whether such gardens lead to a lasting rise in bee numbers."],"questions":[{"type":"short","prompt":"Bees transfer ________ between flowers.","answer":"pollen","why":"Pollen transfer is the pollination process described."},{"type":"short","prompt":"Bees collect a sweet substance called ________.","answer":"nectar","why":"Bees collect nectar."},{"type":"short","prompt":"The researchers worked at ________ University.","answer":"Bellfield","why":"The research team was based at Bellfield University."},{"type":"short","prompt":"How many rooftops were examined?","answer":"24","why":"The team studied twenty-four rooftops."},{"type":"short","prompt":"The project lasted for two ________.","answer":"summers","why":"Data were collected over two summers."},{"type":"short","prompt":"Many urban bees are ________ rather than colonial.","answer":"solitary","why":"The text directly describes solitary bees."},{"type":"short","prompt":"Some bees nest in hollow ________.","answer":"stems","why":"Hollow stems are one of the nesting sites listed."},{"type":"short","prompt":"Gardeners are advised to avoid unnecessary ________.","answer":"pesticides","why":"The advice is to reduce pesticide use."},{"type":"short","prompt":"Linked patches of vegetation were called green ________.","answer":"corridors","why":"Connected patches are green corridors."},{"type":"tfn","prompt":"All bees found on city rooftops live in large colonies.","answer":"FALSE","why":"Many are solitary rather than colonial.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Rooftops with varied flowers usually attracted more bee species.","answer":"TRUE","why":"This is the researchers’ general observation.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The linked school gardens have already increased bee numbers permanently.","answer":"NOT GIVEN","why":"They are planned but their long-term impact has not yet been tested.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"Why should gardeners choose plants that bloom at different times?","options":["To provide flowers across more seasons","To make all bees nest underground","To avoid watering plants altogether","To prevent any insect competition"],"answer":"A","why":"Different flowering seasons provide resources for more of the year."},{"type":"choice","prompt":"What did the researchers say about flower diversity?","options":["It was unnecessary in cities","It alone could not guarantee healthy populations","It mattered only in autumn","It should be replaced by more paving"],"answer":"B","why":"They explicitly warned against relying on diversity alone."}]}]},"moderate":{"label":"Moderate","minutes":60,"passages":[{"title":"Passage 1 · The Return of Night Trains","paras":["Night trains were once an ordinary part of long-distance travel across parts of Europe. Many services disappeared when inexpensive flights expanded and rail operators faced the cost of maintaining sleeper carriages. Recently, however, renewed interest in lower-emission travel has prompted some companies to restore overnight routes. The revival is uneven: demand is strong on certain corridors but insufficient on others.","A sleeper service must solve several practical problems. Passengers expect beds, clean washrooms and a reasonably quiet journey, yet carriages have to meet strict safety standards. Operators also need access to railway tracks at night, when maintenance teams often carry out essential repairs. That competition for track time can be a bigger difficulty than selling tickets.","An overnight journey can replace both a short-haul flight and one night in a hotel. This is attractive to travellers who value arriving in a city centre in the morning. Still, the comparison is not simple. The total environmental impact depends on the electricity used by trains, their occupancy rate, and what alternative journeys passengers would otherwise have made.","An experiment on the Northline route introduced compact private cabins alongside shared sleeping compartments. Surveys found that privacy was highly valued, but the private cabins reduced the total passenger capacity of the train. That trade-off increased the cost per available seat. The operator therefore retained both types rather than making every compartment private.","Policy experts argue that international ticketing is another barrier. A passenger who can compare flights on one screen may have to consult several websites for connecting trains. Some countries are considering common booking standards, although no single system yet covers every operator."],"questions":[{"type":"short","prompt":"What mode of transport helped cause the earlier decline of night trains?","answer":"flights","why":"The growth of cheap flights contributed to the decline."},{"type":"short","prompt":"Sleeper carriages must comply with strict ________ standards.","answer":"safety","why":"Safety standards are specifically mentioned."},{"type":"short","prompt":"At night, rail tracks are also needed by ________ teams.","answer":"maintenance","why":"Maintenance work competes for track time."},{"type":"short","prompt":"Night trains may save travellers the price of a ________.","answer":"hotel","why":"An overnight train can replace a hotel night."},{"type":"short","prompt":"Environmental impact depends partly on how full the train is: its ________ rate.","answer":"occupancy","why":"Occupancy is how full trains are; the passage says this matters."},{"type":"short","prompt":"What name was given to the route used for the cabin experiment?","answer":"Northline","why":"The experimental route was Northline."},{"type":"short","prompt":"Private cabins reduced total passenger ________.","answer":"capacity","why":"Fewer people can travel when space is used for private cabins."},{"type":"short","prompt":"International passengers may need several ________ to arrange rail connections.","answer":"websites","why":"The text refers to consulting multiple websites."},{"type":"tfn","prompt":"Rail operators can use all railway tracks freely at night.","answer":"FALSE","why":"Night maintenance competes with sleeper services.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Passengers in the survey valued privacy.","answer":"TRUE","why":"Privacy was highly valued.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"A single booking system already covers every night-train operator.","answer":"FALSE","why":"No single system covers them all.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"What does the author describe as a major operational barrier?","options":["A shortage of city-centre hotels","Competition for track access","Low demand on every route","A ban on shared compartments"],"answer":"B","why":"Track availability at night can be more problematic than ticket sales."},{"type":"choice","prompt":"Why did Northline keep both private and shared accommodation?","options":["To balance privacy with passenger capacity","To avoid safety inspections","To remove morning arrivals","To make every ticket identical"],"answer":"A","why":"The operator balanced privacy preferences and available capacity."}]},{"title":"Passage 2 · Citizen Sensors and Air Quality","paras":["Air pollution is usually monitored at a small number of expensive reference stations. These stations produce precise data, but they cannot describe every street. In recent years, community groups have begun installing compact sensors on balconies, bicycles and school buildings to add local detail. The devices are affordable, though their readings are not automatically equivalent to those from reference instruments.","In the Harbourfield project, residents deployed 60 sensors over 18 months. Volunteers were trained to identify secure locations away from direct cooking fumes and sheltered from heavy rain. The project measured particulate matter, especially the fine particles known as PM2.5, which can remain suspended in the air for long periods.","Temperature and humidity can distort inexpensive sensors. Researchers therefore compared each model with a reference station and applied a calibration method. They also looked for readings that suddenly rose whenever a nearby resident opened a window above a kitchen. Such spikes were marked for review rather than automatically included in the town-wide estimate.","The data revealed unusually high pollution beside a road where buses frequently waited with engines running. Following discussions, the bus company introduced an anti-idling policy. Researchers were careful not to claim that the sensors had proven the policy would improve health; they had observed local pollution conditions, not long-term medical outcomes.","The project also raised a question about privacy. A sensor fixed to a home could reveal when people were usually present if its public location were too precise. Consequently, the online map displays data within broad grid squares rather than showing the exact address of every volunteer."],"questions":[{"type":"short","prompt":"High-precision pollution measurements normally come from reference ________.","answer":"stations","why":"Reference stations are described as the usual high-precision sources."},{"type":"short","prompt":"How many sensors were deployed in Harbourfield?","answer":"60","why":"The deployment included sixty sensors."},{"type":"short","prompt":"For how many months did the study run?","answer":"18","why":"The period was eighteen months."},{"type":"short","prompt":"Sensors were protected from heavy ________.","answer":"rain","why":"Volunteers had to shelter instruments from heavy rain."},{"type":"short","prompt":"The project focused on fine particles called ________.","answer":"PM2.5","why":"PM2.5 is the named pollutant."},{"type":"short","prompt":"Two environmental factors affecting readings were temperature and ________.","answer":"humidity","why":"Humidity can distort readings."},{"type":"short","prompt":"Researchers used a ________ method to adjust readings.","answer":"calibration","why":"Calibration corrects systematic discrepancies."},{"type":"short","prompt":"The bus company later introduced an anti-________ policy.","answer":"idling","why":"The bus company acted to reduce idling."},{"type":"tfn","prompt":"Low-cost sensors can be treated as accurate without any comparison testing.","answer":"FALSE","why":"Calibration was required against reference stations.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The research proved that the policy reduced hospital admissions.","answer":"FALSE","why":"The researchers did not measure long-term health outcomes.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The online map conceals the exact home addresses of volunteers.","answer":"TRUE","why":"It uses broad grid squares instead of exact locations.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"Why were some sudden peaks in the data marked for review?","options":["They could be affected by nearby indoor sources","They always indicated faulty batteries","They represented data from other countries","They occurred only at reference stations"],"answer":"A","why":"Some spikes coincided with nearby cooking fumes."},{"type":"choice","prompt":"Why did researchers choose broad map squares?","options":["To hide pollution from officials","To protect volunteer privacy","To make sensors more expensive","To simplify the bus timetable"],"answer":"B","why":"The grid protects specific home locations."}]},{"title":"Passage 3 · Bringing Back Floodplains","paras":["For much of the twentieth century, rivers were straightened and isolated from their floodplains by embankments. The purpose was often to protect farmland or speed the movement of water through towns. These interventions changed the timing and location of floods, sometimes passing the problem downstream rather than removing it.","Floodplain restoration aims to give rivers more space to spread during periods of heavy flow. In the fictional district of Carriston, engineers purchased low-lying fields and removed two short sections of embankment. The design created temporary storage areas that could fill with water during storms and drain slowly afterward. The land was not intended to remain underwater permanently.","Before the project, scientists used historical maps, field measurements and a hydraulic model to predict possible effects. They had to account for uncertainty: a simulation based on one extreme storm could not reliably describe every future event. Local residents initially feared that the new channels would attract mosquitoes, while some farmers worried about losing access to tracks across their fields.","After construction, river levels were monitored continuously and birds were counted during seasonal surveys. Early results suggested that peak flows downstream were slightly lower during several storms. Yet researchers refused to attribute every change to the restoration because rainfall patterns had also varied. They used an upstream monitoring station as a comparison point.","The restored land subsequently supported reed beds and shallow pools. The council plans to expand footpaths, but ecologists recommend restricting visitor access near nesting sites in spring. The programme illustrates that flood management can also create ecological benefits, provided the different goals are negotiated openly."],"questions":[{"type":"short","prompt":"Rivers were often separated from floodplains by ________.","answer":"embankments","why":"Embankments formed barriers between rivers and floodplains."},{"type":"short","prompt":"Where did the demonstration restoration take place?","answer":"Carriston","why":"The fictional district was Carriston."},{"type":"short","prompt":"The new storage areas fill during ________.","answer":"storms","why":"Storage areas fill during storms."},{"type":"short","prompt":"Water is intended to drain away ________ after a flood.","answer":"slowly","why":"They drain slowly afterward."},{"type":"short","prompt":"Scientists consulted historical ________ before construction.","answer":"maps","why":"Historical maps were used in design."},{"type":"short","prompt":"The prediction tool used by engineers was a hydraulic ________.","answer":"model","why":"The text names a hydraulic model."},{"type":"short","prompt":"One concern was that the restored channels might attract ________.","answer":"mosquitoes","why":"Some residents feared mosquitoes."},{"type":"short","prompt":"River levels were monitored ________ following the work.","answer":"continuously","why":"Continuous monitoring followed construction."},{"type":"short","prompt":"An ________ monitoring station provided comparative data.","answer":"upstream","why":"The upstream station was a comparison point."},{"type":"tfn","prompt":"The restored fields were designed to stay flooded throughout the year.","answer":"FALSE","why":"The fields should drain after storms.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The changes in downstream flows could be explained entirely by restoration.","answer":"FALSE","why":"Researchers cautioned that rainfall varied too.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"New footpaths are planned, with limits near nesting sites in spring.","answer":"TRUE","why":"The council plans paths and ecologists recommend limits in spring.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"What is an important limitation of the early results?","options":["No river levels were measured","Weather conditions also changed","The project was designed only for tourism","The embankments were not altered"],"answer":"B","why":"Rainfall variability makes causation uncertain."},{"type":"choice","prompt":"Why might spring visitors be restricted?","options":["To allow wildlife to nest","To increase floodwater storage","To keep farmers off public paths","To maintain the hydraulic model"],"answer":"A","why":"Nesting wildlife needs protection in spring."}]}]},"high":{"label":"High","minutes":60,"passages":[{"title":"Passage 1 · Listening to Wind Turbines","paras":["Wind turbines are designed to operate for decades, yet a single unexpected failure can halt electricity production and require expensive repairs. Traditional maintenance combines routine inspections with replacement after parts show visible wear. Predictive maintenance takes a different approach: it analyses measurements gathered during ordinary operation and estimates whether a component is moving toward failure.","One research programme studied vibration signals from turbine gearboxes. Sensors recorded how strongly the machinery moved at various frequencies. Engineers trained a statistical model on periods when the equipment was known to be healthy. The model then flagged patterns that differed substantially from this baseline. An anomaly was not, however, treated as a confirmed defect; unusual readings can arise from changing wind conditions or a sensor that has become loose.","The researchers tested the system at three wind farms with different climates. Their main challenge was transferring a model from one site to another. A model that performed well in calm coastal conditions sometimes produced too many warnings in colder, more turbulent locations. Rather than simply increasing the alarm threshold, the team incorporated information about ambient temperature and operating load.","False alarms have real costs. Each warning can prompt engineers to stop a turbine, inspect equipment and perhaps hire a crane. Missing an imminent failure also has costs, which may be even greater. Operators therefore need to choose a decision threshold that reflects the relative consequences of false warnings and missed faults.","The project concluded that predictive systems should support—not replace—experienced engineers. Staff were encouraged to record why an alert was accepted or dismissed so that the next model revision could learn from those decisions. The researchers also recommended retaining raw signals for independent audits, while acknowledging that storing large volumes of data is expensive."],"questions":[{"type":"short","prompt":"The investigated turbine component was the ________.","answer":"gearbox","why":"The research focused on gearbox vibrations.","accept":["gearboxes"]},{"type":"short","prompt":"Sensors measured movement at different ________.","answer":"frequencies","why":"The signals were analysed at different frequencies."},{"type":"short","prompt":"Healthy operation was used to establish a ________.","answer":"baseline","why":"A healthy reference baseline was learned."},{"type":"short","prompt":"Unusual readings do not necessarily prove a ________.","answer":"defect","why":"An anomaly is not necessarily a defect."},{"type":"short","prompt":"The research involved ________ wind farms.","answer":"three","why":"Three sites were studied."},{"type":"short","prompt":"Models trained in one location could create excessive ________ elsewhere.","answer":"warnings","why":"Cross-site transfer sometimes caused too many warnings."},{"type":"short","prompt":"The improved model included information about ambient ________.","answer":"temperature","why":"Temperature was included as an explanatory variable."},{"type":"short","prompt":"Some inspections might require hiring a ________.","answer":"crane","why":"A crane was listed among potential costs."},{"type":"tfn","prompt":"A vibration anomaly was always treated as proof of mechanical failure.","answer":"FALSE","why":"Anomalies could have other causes.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The team wanted to eliminate experienced engineers from decision-making.","answer":"FALSE","why":"Systems were meant to support, not replace them.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The researchers encouraged retention of unprocessed signals for audits.","answer":"TRUE","why":"They recommended retaining raw signals for independent audits.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"Why does the alarm threshold matter?","options":["It changes the price of electricity directly","It balances missed failures against false alarms","It determines the number of wind farms","It prevents sensors from ever loosening"],"answer":"B","why":"Both false positives and missed faults have consequences."},{"type":"choice","prompt":"What was a difficulty in transferring the model to another site?","options":["Different environmental conditions","A ban on statistical methods","The absence of any turbine gearbox","No measurements during operation"],"answer":"A","why":"Models performed differently across climates."}]},{"title":"Passage 2 · The Map Beneath the Map","paras":["Historic maps appear to offer direct windows onto the past. Yet every map is a selective representation, shaped by its intended audience, the tools available to its maker and the political interests of its publisher. Scholars working with old atlases therefore examine not only what is shown, but also what is missing. A village omitted from a printed map may have existed for centuries; it simply may not have met the cartographer’s criteria for inclusion.","At the Northgate Archive, a collection of coastal maps contains several palimpsests—sheets on which earlier marks were partly erased and new information drawn over them. Conservators found that certain harbours appeared beneath later coastlines. To investigate without damaging fragile paper, the team used multispectral imaging, capturing the same sheet under several wavelengths of light. Some faded pigments became easier to distinguish in these images.","Interpreting the results required caution. An apparent coastline might be a planning sketch rather than an observation made from a ship. Researchers compared the hidden features with shipping registers, merchants’ letters and dated survey notes. In one case, a harbour first thought to be a lost settlement turned out to be a proposed canal entrance that was never built.","Digitisation also raised difficult choices. High-resolution scans allow visitors to zoom into minute details, but an online viewer can accidentally imply more precision than the original survey possessed. For that reason, the archive displays a scale warning alongside each image. It also links different editions rather than presenting one map as the final authoritative version.","The project has attracted interest from local historians and environmental researchers. Changes in shoreline position can reveal useful long-term patterns, although the cartographic record is too uneven to substitute for modern geological measurements. The archive describes its collection as evidence to be interpreted, not a series of perfectly accurate snapshots."],"questions":[{"type":"short","prompt":"An omitted village may not have met the mapmaker’s ________ for inclusion.","answer":"criteria","why":"Omission may reflect selection criteria."},{"type":"short","prompt":"Sheets containing erased earlier drawings are called ________.","answer":"palimpsests","why":"The text defines palimpsests."},{"type":"short","prompt":"The maps are held at the ________ Archive.","answer":"Northgate","why":"The collection belongs to Northgate Archive."},{"type":"short","prompt":"The conservators used multispectral ________.","answer":"imaging","why":"Multispectral imaging was used."},{"type":"short","prompt":"The technique photographed sheets under multiple ________.","answer":"wavelengths","why":"Several wavelengths of light were captured."},{"type":"short","prompt":"Researchers checked hidden features against shipping ________.","answer":"registers","why":"Shipping registers were among the comparison sources."},{"type":"short","prompt":"A supposed lost harbour was actually a planned ________ entrance.","answer":"canal","why":"It was a canal entrance never built."},{"type":"short","prompt":"The digital viewer displays a ________ warning.","answer":"scale","why":"It warns users about scale and precision."},{"type":"tfn","prompt":"A map that fails to show a settlement proves that settlement did not exist.","answer":"FALSE","why":"Omissions can reflect cartographic choices.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The team damaged some maps to uncover hidden coastlines.","answer":"FALSE","why":"The investigation was designed to avoid damage.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"The archive links several editions rather than privileging one as definitive.","answer":"TRUE","why":"Multiple editions are linked for comparison.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"What is a key risk of detailed online scans?","options":["They can suggest unjustified accuracy","They prevent the comparison of editions","They erase all original pigments","They reveal no information about scale"],"answer":"A","why":"Zoom may falsely imply the original map was equally precise."},{"type":"choice","prompt":"Why did researchers consult written records?","options":["To identify the purpose of unclear marks","To replace all maps with letters","To calculate modern passenger numbers","To choose paper for the exhibition"],"answer":"A","why":"External records helped distinguish a real harbour from an unrealised proposal."}]},{"title":"Passage 3 · When Algorithms Allocate Services","paras":["Public agencies increasingly use statistical models to decide which applications need urgent attention. Such systems may rank requests for housing inspections, identify areas needing additional social services or help staff prioritise limited resources. Their appeal lies in speed and consistency. Their danger is that a mathematical ranking may appear neutral even when the data used to construct it reflect unequal access to services in the past.","Consider an inspection model trained on previous complaints. Neighbourhoods where residents frequently report hazards may appear to have the greatest need. Yet low complaint numbers could instead reflect language barriers, limited internet access or distrust of authorities. If a model simply repeats historical patterns, it may direct fewer inspections to places where problems are least visible in official records.","A research team in the fictional city of Eastmere compared a complaint-based system with an alternative using building age, repair records and independent surveys. The alternative did not eliminate uncertainty, but it revealed districts overlooked by the complaint-only model. The researchers argued that evaluation should examine who benefits from decisions, not merely how accurately the system reproduces historical labels.","One proposed safeguard is a human review stage in which staff can challenge an automated recommendation and record their reasoning. Another is regular publication of aggregate outcomes. However, transparency is not simply the release of computer code: meaningful explanations must be understandable to the residents affected by the decisions.","There are limits to every intervention. A human reviewer can carry personal biases, and a more complex model may be difficult to explain. The researchers therefore favoured iterative audits, including feedback from community organisations. They also called for a clear appeals process so that residents could dispute an outcome without having to understand the software that produced it.","The team’s central conclusion was that public-sector algorithms should be assessed as parts of social institutions, rather than isolated technical products. An apparently small design decision—such as which records count as evidence—can change who receives assistance first."],"questions":[{"type":"short","prompt":"Some models rank requests for housing ________.","answer":"inspections","why":"Housing inspections are one application."},{"type":"short","prompt":"A complaint-based model is trained on earlier ________.","answer":"complaints","why":"The source data include previous complaints."},{"type":"short","prompt":"Lower reporting may reflect limited internet ________.","answer":"access","why":"Internet access affects complaint rates."},{"type":"short","prompt":"The study took place in the fictional city of ________.","answer":"Eastmere","why":"The comparison was carried out in Eastmere."},{"type":"short","prompt":"The alternative model used data about building ________.","answer":"age","why":"Building age was one predictor."},{"type":"short","prompt":"Independent ________ supplied additional evidence.","answer":"surveys","why":"The model used independent surveys."},{"type":"short","prompt":"Staff should record the reasons for challenging a model’s ________.","answer":"recommendation","why":"Human review should document challenges to recommendations."},{"type":"short","prompt":"Researchers proposed repeated ________ of the system.","answer":"audits","why":"Iterative audits were recommended."},{"type":"short","prompt":"Residents should have access to an ________ process.","answer":"appeals","why":"An appeals process is proposed."},{"type":"tfn","prompt":"A complaint-based model always identifies communities with the greatest need.","answer":"FALSE","why":"Under-reporting can hide unmet needs.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Publishing source code by itself guarantees public understanding.","answer":"FALSE","why":"Meaningful transparency requires accessible explanations.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"tfn","prompt":"Human reviewers can introduce bias into decisions.","answer":"TRUE","why":"Human review is not automatically impartial.","options":["TRUE","FALSE","NOT GIVEN"]},{"type":"choice","prompt":"What did the alternative model reveal?","options":["Districts missing from the original prioritisation","That complaint records were perfectly complete","That building age had no relationship to need","That every public decision can be automated"],"answer":"A","why":"Additional evidence highlighted overlooked districts."},{"type":"choice","prompt":"What is the author’s main argument?","options":["Algorithms should replace social institutions","Evaluation must consider social consequences","Historical records are always reliable","Complex models should never be used"],"answer":"B","why":"The central conclusion is institutional, not purely technical."}]}]}}};
